typedef struct SidereonTlePair {
    /**
     * Null-terminated TLE line 1.
     */
    const char *line1;
    /**
     * Null-terminated TLE line 2.
     */
    const char *line2;
} SidereonTlePair;

/**
 * Options for the pseudorange variance model, mirroring
 * sidereon_core::quality::PseudorangeVarianceOptions.
 */
typedef struct SidereonPseudorangeVarianceOptions {
    /**
     * Zenith standard-deviation term, meters.
     */
    double a_m;
    /**
     * Elevation-scaled standard-deviation term, meters.
     */
    double b_m;
    /**
     * One of SidereonPseudorangeVarianceModel as uint32_t.
     */
    uint32_t model;
    /**
     * Whether cn0_dbhz is supplied (required for the ElevationCn0 model).
     */
    bool has_cn0;
    /**
     * Carrier-to-noise density, dB-Hz, used when has_cn0 is true.
     */
    double cn0_dbhz;
    /**
     * C/N0 scaling term, meters squared.
     */
    double cn0_scale_m2;
} SidereonPseudorangeVarianceOptions;

/**
 * One linearized range measurement for sidereon_raim_fde_design, mirroring
 * sidereon_core::quality::RangeFdeRow. `design_row` points to `design_dim`
 * doubles (the design-matrix row); every row must carry the same `design_dim`,
 * which is the estimated state dimension.
 */
typedef struct SidereonRangeFdeRow {
    /**
     * Stable measurement identifier (e.g. a satellite token "G01").
     */
    const char *id;
    /**
     * Observed-minus-computed range residual, metres.
     */
    double residual_m;
    /**
     * Design-matrix row: partials with respect to each estimated state parameter.
     */
    const double *design_row;
    /**
     * Length of `design_row`, the estimated state dimension.
     */
    size_t design_dim;
    /**
     * Inverse-variance weight 1/sigma^2; must be finite and strictly positive.
     */
    double weight;
} SidereonRangeFdeRow;

/**
 * Options for sidereon_raim_fde_design, mirroring
 * sidereon_core::quality::RangeFdeOptions. Initialize with
 * sidereon_range_fde_options_init, then override fields.
 */
typedef struct SidereonRangeFdeOptions {
    /**
     * False-alarm probability for the global chi-square test, in (0, 1).
     */
    double p_fa;
    /**
     * Maximum number of measurements the exclusion loop may remove. The
     * default, 1, is RTKLIB demo5's single raim_fde exclusion; a larger budget
     * repeats the test and a fresh leave-one-out search on the remaining set.
     */
    size_t max_exclusions;
    /**
     * Minimum redundancy (degrees of freedom) an exclusion must leave behind.
     */
    size_t min_redundancy;
    /**
     * The largest unweighted post-fit residual RMS, metres, an exclusion may
     * leave; the default is RTKLIB demo5's initial rms of 100 m.
     */
    double max_exclusion_rms_m;
} SidereonRangeFdeOptions;

/**
 * Per-measurement FDE diagnostic, mirroring
 * sidereon_core::quality::RangeMeasurementDiagnostic, in input order.
 */
typedef struct SidereonRangeFdeDiagnostic {
    /**
     * Measurement identifier, echoed from the input row.
     */
    struct SidereonRtkId id;
    /**
     * Whether the FDE loop excluded this measurement.
     */
    bool excluded;
    /**
     * Post-fit residual against the protected state correction, metres.
     */
    double post_fit_residual_m;
    /**
     * Standardized post-fit residual post_fit_residual_m * sqrt(weight).
     */
    double normalized_residual;
} SidereonRangeFdeDiagnostic;

/**
 * Global chi-square consistency test, mirroring
 * sidereon_core::quality::RangeChiSquareTest.
 */
typedef struct SidereonRangeChiSquareTest {
    /**
     * Weighted sum of squared post-fit residuals, v^T W v.
     */
    double weighted_sum_squares;
    /**
     * Redundancy n_used - n_state.
     */
    int64_t dof;
    /**
     * Whether a chi-square threshold is present (true when dof > 0).
     */
    bool has_threshold;
    /**
     * Chi-square threshold chi2_inv(1 - p_fa, dof), 0 when absent.
     */
    double threshold;
    /**
     * False when dof <= 0 (no redundancy to test against).
     */
    bool testable;
    /**
     * True when the test statistic exceeds the threshold (a fault remains).
     */
    bool fault_detected;
} SidereonRangeChiSquareTest;

/**
 * Fitted reduced-orbit mean elements. The `model` field is a
 * SidereonReducedOrbitModel value (cast to uint32_t).
 */
typedef struct SidereonReducedOrbitElements {
    /**
     * Model these elements belong to (SidereonReducedOrbitModel as uint32_t).
     */
    uint32_t model;
    /**
     * Reference epoch t0.
     */
    struct SidereonCalendarEpoch epoch;
    /**
     * Semi-major axis a, meters.
     */
    double a_m;
    /**
     * Eccentricity.
     */
    double e;
    /**
     * Inclination i, radians.
     */
    double i_rad;
    /**
     * RAAN at t0, radians.
     */
    double raan_rad;
    /**
     * Fitted nodal regression rate, radians per second.
     */
    double raan_rate_rad_s;
    /**
     * J2 nodal-regression seed for raan_rate, radians per second.
     */
    double raan_rate_j2_rad_s;
    /**
     * Argument of latitude at t0, radians.
     */
    double arg_lat_rad;
    /**
     * Mean motion n, radians per second.
     */
    double mean_motion_rad_s;
    /**
     * Eccentricity vector component h = e*sin(omega).
     */
    double h;
    /**
     * Eccentricity vector component k = e*cos(omega).
     */
    double k;
    /**
     * Argument of perigee omega, radians.
     */
    double arg_perigee_rad;
} SidereonReducedOrbitElements;

/**
 * One fit/drift truth sample: a calendar epoch and an ECEF (ITRF) position.
 */
typedef struct SidereonEcefSample {
    /**
     * Sample epoch.
     */
    struct SidereonCalendarEpoch epoch;
    /**
     * ECEF X, meters.
     */
    double x_m;
    /**
     * ECEF Y, meters.
     */
    double y_m;
    /**
     * ECEF Z, meters.
     */
    double z_m;
} SidereonEcefSample;

/**
 * One per-epoch drift entry from sidereon_reduced_orbit_drift_report_entries.
 */
typedef struct SidereonReducedOrbitDriftEntry {
    /**
     * Epoch evaluated.
     */
    struct SidereonCalendarEpoch epoch;
    /**
     * Position error magnitude (model minus truth), meters.
     */
    double error_m;
} SidereonReducedOrbitDriftEntry;

/**
 * Aggregate drift summary from sidereon_reduced_orbit_drift_report_summary.
 */
typedef struct SidereonReducedOrbitDriftSummary {
    /**
     * Maximum error over the horizon, meters.
     */
    double max_m;
    /**
     * RMS error over the horizon, meters.
     */
    double rms_m;
    /**
     * Whether the error crossed the requested threshold over the horizon.
     */
    bool has_threshold_crossing;
    /**
     * Index of the first threshold-crossing entry within the drift report
     * entries (sidereon_reduced_orbit_drift_report_entries), whose `epoch` field
     * is the crossing epoch. Valid only when has_threshold_crossing is true; the
     * crossing epoch is read from that entry rather than fabricated here.
     */
    size_t threshold_index;
} SidereonReducedOrbitDriftSummary;

/**
 * Sampling window and cadence for source-backed reduced-orbit drivers.
 */
typedef struct SidereonReducedOrbitSourceSampling {
    /**
     * Inclusive sample window start.
     */
    struct SidereonCalendarEpoch t0;
    /**
     * Inclusive sample window end.
     */
    struct SidereonCalendarEpoch t1;
    /**
     * Sampling cadence, seconds.
     */
    double cadence_s;
} SidereonReducedOrbitSourceSampling;

/**
 * Source-backed reduced-orbit drift options.
 */
typedef struct SidereonReducedOrbitSourceDriftOptions {
    /**
     * Sampling window and cadence.
     */
    struct SidereonReducedOrbitSourceSampling sampling;
    /**
     * Threshold used to mark the first crossing, meters.
     */
    double threshold_m;
} SidereonReducedOrbitSourceDriftOptions;

/**
 * Residual statistics from a reduced-orbit fit, meters.
 */
typedef struct SidereonReducedOrbitFitStats {
    /**
     * RMS GCRS position residual over the samples, meters.
     */
    double rms_m;
    /**
     * Maximum GCRS position residual over the samples, meters.
     */
    double max_m;
    /**
     * Number of samples used in the fit.
     */
    size_t n_samples;
} SidereonReducedOrbitFitStats;

/**
 * Source-backed reduced-orbit fit options.
 */
typedef struct SidereonReducedOrbitSourceFitOptions {
    /**
     * Sampling window and cadence.
     */
    struct SidereonReducedOrbitSourceSampling sampling;
    /**
     * Model to fit, as SidereonReducedOrbitModel.
     */
    uint32_t model;
} SidereonReducedOrbitSourceFitOptions;

/**
 * Source-backed piecewise fit metadata.
 */
typedef struct SidereonReducedOrbitPiecewiseSourceFitStats {
    /**
     * Number of samples requested from the source before unavailable epochs
     * were skipped.
     */
    size_t requested_samples;
    /**
     * Number of source samples used across all fitted segments.
     */
    size_t used_samples;
} SidereonReducedOrbitPiecewiseSourceFitStats;

/**
 * Residual statistics plus source-sampling metadata from a source-backed fit.
 */
typedef struct SidereonReducedOrbitSourceFitStats {
    /**
     * Fit residual statistics.
     */
    struct SidereonReducedOrbitFitStats fit;
    /**
     * Number of samples requested from the source before unavailable epochs
     * were skipped.
     */
    size_t requested_samples;
} SidereonReducedOrbitSourceFitStats;

/**
 * Summary metadata for a fitted piecewise reduced-orbit model.
 */
typedef struct SidereonReducedOrbitPiecewiseInfo {
    /**
     * Model fitted in every segment (SidereonReducedOrbitModel as uint32_t).
     */
    uint32_t model;
    /**
     * Time scale used for fit and evaluation (SidereonTimeScale as uint32_t).
     */
    uint32_t scale;
    /**
     * Advertised coverage start.
     */
    struct SidereonCalendarEpoch t0;
    /**
     * Advertised coverage end, inclusive on the final segment.
     */
    struct SidereonCalendarEpoch t1;
    /**
     * Rounded segment length used to tile the window, seconds.
     */
    int64_t segment_s;
    /**
     * Number of fitted segments.
     */
    size_t n_segments;
} SidereonReducedOrbitPiecewiseInfo;

/**
 * One fitted piecewise segment and its reduced-orbit fit.
 */
typedef struct SidereonReducedOrbitPiecewiseSegment {
    /**
     * Inclusive segment start.
     */
    struct SidereonCalendarEpoch t0;
    /**
     * Segment end, exclusive except for the final segment.
     */
    struct SidereonCalendarEpoch t1;
    /**
     * Fitted mean elements for this segment.
     */
    struct SidereonReducedOrbitElements elements;
    /**
     * Fit residual statistics for this segment.
     */
    struct SidereonReducedOrbitFitStats stats;
} SidereonReducedOrbitPiecewiseSegment;

/**
 * Options for classical internal and external reliability design.
 */
typedef struct SidereonReliabilityOptions {
    /**
     * Two-sided false-alarm probability for one w-test.
     */
    double alpha;
    /**
     * Missed-detection probability for the target bias.
     */
    double beta;
    /**
     * Whether lambda0_override carries a precomputed noncentrality value.
     */
    bool has_lambda0_override;
    /**
     * Precomputed noncentrality value, used only when has_lambda0_override is true.
     */
    double lambda0_override;
    /**
     * Redundancy below which an observation is reported as uncheckable.
     */
    double min_redundancy;
} SidereonReliabilityOptions;

/**
 * One range row for pre-data reliability design.
 */
typedef struct SidereonRangeReliabilityRow {
    /**
     * Null-terminated observation identifier, at most 64 bytes.
     */
    const char *id;
    /**
     * Linearized design row for this range observation.
     */
    const double *design_row;
    /**
     * Number of entries in design_row.
     */
    size_t design_dim;
    /**
     * Externally supplied one-sigma range model, meters.
     */
    double sigma_m;
} SidereonRangeReliabilityRow;

/**
 * Reliability diagnostics for one observation.
 */
typedef struct SidereonObservationReliability {
    /**
     * Observation identifier, null-terminated.
     */
    struct SidereonRtkId id;
    /**
     * Redundancy number, the checked fraction of this observation.
     */
    double redundancy;
    /**
     * Whether mdb_m carries a minimal detectable bias.
     */
    bool has_mdb_m;
    /**
     * Minimal detectable bias, meters, when present.
     */
    double mdb_m;
    /**
     * Whether external_enu_m carries an external effect vector.
     */
    bool has_external_enu_m;
    /**
     * External effect vector, meters, when present.
     */
    double external_enu_m[3];
    /**
     * Whether bias_to_noise carries a state-space bias-to-noise ratio.
     */
    bool has_bias_to_noise;
    /**
     * Bias-to-noise ratio, when present.
     */
    double bias_to_noise;
    /**
     * True when the observation redundancy is below the configured floor.
     */
    bool uncheckable;
} SidereonObservationReliability;

/**
 * Aggregate reliability diagnostics for a design.
 */
typedef struct SidereonReliabilitySummary {
    /**
     * Number of observations in the design.
     */
    size_t n_obs;
    /**
     * Number of estimated parameters in the design.
     */
    size_t n_params;
    /**
     * Algebraic degrees of freedom.
     */
    size_t dof;
    /**
     * Sum of per-observation redundancy numbers.
     */
    double sum_redundancy;
    /**
     * Noncentrality parameter used for MDB calculations.
     */
    double lambda0;
    /**
     * Whether max_mdb_id and max_mdb_m carry a checkable observation.
     */
    bool has_max_mdb_m;
    /**
     * Observation identifier for the largest finite MDB.
     */
    struct SidereonRtkId max_mdb_id;
    /**
     * Largest finite MDB, meters, when present.
     */
    double max_mdb_m;
    /**
     * Observation identifier for the smallest redundancy number.
     */
    struct SidereonRtkId min_redundancy_id;
    /**
     * Smallest redundancy number.
     */
    double min_redundancy;
    /**
     * Count of observations reported as uncheckable.
     */
    size_t n_uncheckable;
} SidereonReliabilitySummary;

/**
 * Jarque-Bera normality test result.
 */
typedef struct SidereonJarqueBera {
    /**
     * Test statistic `n/6 * (S^2 + K^2/4)`.
     */
    double statistic;
    /**
     * Upper-tail chi-square(2) p-value `exp(-statistic/2)`.
     */
    double p_value;
} SidereonJarqueBera;

/**
 * Sample mean, variance, skewness, and kurtosis of a residual set. Mirrors the
 * core `MomentStats`.
 */
typedef struct SidereonResidualMoments {
    /**
     * Arithmetic mean.
     */
    double mean;
    /**
     * Population (biased) variance, the second central moment.
     */
    double variance;
    /**
     * Sample skewness (biased or bias-corrected per the request).
     */
    double skewness;
    /**
     * Sample kurtosis: excess (Gaussian -> 0) when fisher, Pearson otherwise.
     */
    double kurtosis_excess;
} SidereonResidualMoments;

/**
 * Shapiro-Wilk normality test result.
 */
typedef struct SidereonShapiroWilk {
    /**
     * The `W` statistic in `(0, 1]`.
     */
    double w;
    /**
     * Upper-tail p-value for the normality null.
     */
    double p_value;
} SidereonShapiroWilk;

/**
 * A radio-frequency link budget, mirroring sidereon_core::astro::rf::LinkBudget.
 */
typedef struct SidereonLinkBudget {
    /**
     * Effective isotropic radiated power, dBW.
     */
    double eirp_dbw;
    /**
     * Free-space path loss, dB.
     */
    double fspl_db;
    /**
     * Receiver gain-over-temperature, dB/K.
     */
    double receiver_gt_dbk;
    /**
     * Other losses, dB.
     */
    double other_losses_db;
    /**
     * Required carrier-to-noise density, dB-Hz.
     */
    double required_cn0_dbhz;
} SidereonLinkBudget;

/**
 * Typed detail of a RINEX clock failure. Only the fields the kind names carry
 * meaning. Text parts are read with the text route of the owner (a
 * SidereonRinexClockResult or a diagnostic); each has_ flag says whether the
 * failure carries that part, since a part can itself be empty.
 */
typedef struct SidereonRinexClockError {
    /**
     * Which failure was reported.
     */
    enum SidereonRinexClockErrorKind kind;
    /**
     * Whether line carries a line number.
     */
    bool has_line;
    /**
     * One-based input line number.
     */
    size_t line;
    /**
     * Whether time_scale carries the refused scale.
     */
    bool has_time_scale;
    /**
     * The refused time scale, as SidereonTimeScale.
     */
    uint32_t time_scale;
    /**
     * Whether the failure names a field.
     */
    bool has_field;
    /**
     * Whether the failure gives a reason.
     */
    bool has_reason;
    /**
     * Whether the failure carries record text.
     */
    bool has_record;
    /**
     * Whether the failure names a record type.
     */
    bool has_record_type;
    /**
     * Whether the failure carries a field value.
     */
    bool has_value;
} SidereonRinexClockError;

/**
 * A line a lossy read kept without reading it as a record, or a header
 * time-system error, with the typed failure. Its text parts are read with
 * sidereon_rinex_clock_diagnostic_text.
 */
typedef struct SidereonClockDiagnostic {
    /**
     * One-based line number.
     */
    size_t line;
    /**
     * The failure.
     */
    struct SidereonRinexClockError error;
} SidereonClockDiagnostic;

/**
 * One complete RINEX clock series sample.
 *
 * additional_values holds the declared values after the bias, in the Table A16
 * order (bias sigma in seconds, clock rate, clock rate sigma, clock
 * acceleration in 1/s, clock acceleration sigma in 1/s); entries at and past
 * additional_value_count are NaN. Values a record carries beyond its declared
 * count are not part of the sample; the record reports them as surplus values.
 */
typedef struct SidereonClockPoint {
    /**
     * Scale-tagged sample epoch.
     */
    struct SidereonClockEpoch epoch;
    /**
     * Satellite clock bias, seconds.
     */
    double bias_s;
    /**
     * Number of declared values after the bias, 0..=5.
     */
    size_t additional_value_count;
    /**
     * The declared values after the bias.
     */
    double additional_values[SIDEREON_CLOCK_MAX_ADDITIONAL_VALUES];
} SidereonClockPoint;

/**
 * One sample of a product built with sidereon_rinex_clock_from_points.
 */
typedef struct SidereonClockSatellitePoint {
    /**
     * Satellite name, null-terminated, exactly as the product holds it.
     */
    struct SidereonSatelliteToken satellite;
    /**
     * The sample, every declared value included.
     */
    struct SidereonClockPoint point;
} SidereonClockSatellitePoint;

/**
 * Fixed-width summary of a RINEX clock product.
 */
typedef struct SidereonRinexClockInfo {
    /**
     * Whether version carries the declared format version.
     */
    bool has_version;
    /**
     * Declared format version; for a built product, the version it is written
     * in.
     */
    double version;
    /**
     * Whether layout carries the column layout.
     */
    bool has_layout;
    /**
     * Column layout records are read and written in, as SidereonClockLayout.
     */
    uint32_t layout;
    /**
     * Whether satellite_system carries the `RINEX VERSION / TYPE` system code.
     */
    bool has_satellite_system;
    /**
     * Satellite system code point (`G`, `R`, `E`, `C`, `I`, `J`, `S` or `M`).
     */
    uint32_t satellite_system;
    /**
     * Whether time_system carries the product's time system.
     */
    bool has_time_system;
    /**
     * The declared, defaulted or built time system, as
     * SidereonClockTimeSystem.
     */
    uint32_t time_system;
    /**
     * How the time system was established, as SidereonClockTimeSystemStatus.
     */
    uint32_t time_system_status;
    /**
     * Number of labels an Unrecognized or Conflicting status carries.
     */
    size_t time_system_label_count;
    /**
     * Whether time_scale carries the scale record epochs are read in. False
     * when the time system is missing, unrecognized, conflicting or has no
     * core scale (`IRN`).
     */
    bool has_time_scale;
    /**
     * The time scale, as SidereonTimeScale.
     */
    uint32_t time_scale;
    /**
     * Number of header lines; a built product has none.
     */
    size_t header_record_count;
    /**
     * Number of data records of every type.
     */
    size_t record_count;
    /**
     * Number of satellites with a clock series.
     */
    size_t series_count;
    /**
     * Number of samples across every satellite series.
     */
    size_t sample_count;
    /**
     * Number of records outside the satellite series.
     */
    size_t skipped_record_count;
    /**
     * Number of lines a lossy read kept without reading them, plus header
     * time-system errors.
     */
    size_t diagnostic_count;
    /**
     * Number of non-fatal findings about how the product was read.
     */
    size_t notice_count;
    /**
     * The engine's name for `time_system` when it reads UNKNOWN: a value a later
     * engine adds that this binding has no code for yet. Empty otherwise.
     */
    char time_system_unknown_variant[SIDEREON_UNKNOWN_VARIANT_C_BYTES];
    /**
     * The engine's name for `time_system_status` when it reads UNKNOWN: a value a later
     * engine adds that this binding has no code for yet. Empty otherwise.
     */
    char time_system_status_unknown_variant[SIDEREON_UNKNOWN_VARIANT_C_BYTES];
} SidereonRinexClockInfo;

/**
 * One notice about how a RINEX clock product was read.
 */
typedef struct SidereonClockNotice {
    /**
     * Which finding, as SidereonClockNoticeKind.
     */
    uint32_t kind;
    /**
     * Whether time_system carries a system.
     */
    bool has_time_system;
    /**
     * The system, as SidereonClockTimeSystem.
     */
    uint32_t time_system;
    /**
     * Whether line carries a header line number.
     */
    bool has_line;
    /**
     * One-based header line number.
     */
    size_t line;
    /**
     * Whether records and first_line carry a record count.
     */
    bool has_records;
    /**
     * Number of records.
     */
    size_t records;
    /**
     * One-based line number of the first.
     */
    size_t first_line;
    /**
     * The engine's name for `kind` when it reads UNKNOWN: a value a later
     * engine adds that this binding has no code for yet. Empty otherwise.
     */
    char kind_unknown_variant[SIDEREON_UNKNOWN_VARIANT_C_BYTES];
    /**
     * The engine's name for `time_system` when it reads UNKNOWN: a value a later
     * engine adds that this binding has no code for yet. Empty otherwise.
     */
    char time_system_unknown_variant[SIDEREON_UNKNOWN_VARIANT_C_BYTES];
} SidereonClockNotice;

/**
 * One departure the RINEX clock writer emitted. The record's name and the
 * epoch fields as written are read with
 * sidereon_rinex_clock_result_departure_text.
 */
typedef struct SidereonClockWriteDeparture {
    /**
     * Which departure, as SidereonClockWriteDepartureKind.
     */
    uint32_t kind;
    /**
     * Index of the record, in record order.
     */
    size_t record;
    /**
     * Whether epoch carries the epoch the product holds.
     */
    bool has_epoch;
    /**
     * The epoch the product holds.
     */
    struct SidereonClockEpoch epoch;
    /**
     * The engine's name for the first value in this struct that reads
     * UNKNOWN: a value a later engine adds that this binding has no code for
     * yet. Empty when no value reads UNKNOWN.
     */
    char unknown_variant[SIDEREON_UNKNOWN_VARIANT_C_BYTES];
} SidereonClockWriteDeparture;

/**
 * The fixed-width outcome of one RINEX clock operation.
 */
typedef struct SidereonRinexClockOutcome {
    /**
     * Whether the operation succeeded.
     */
    bool is_ok;
    /**
     * SIDEREON_STATUS_OK on success, otherwise
     * SIDEREON_STATUS_INVALID_ARGUMENT, which every failure maps to.
     */
    enum SidereonStatus status;
    /**
     * The typed failure; kind is None when is_ok is true.
     */
    struct SidereonRinexClockError error;
} SidereonRinexClockOutcome;

/**
 * Values for one record in a sidereon_rinex_clock_set_records_values batch.
 */
typedef struct SidereonClockRecordValues {
    /**
     * Index of the record, in record order.
     */
    size_t index;
    /**
     * Number of values in values, bias first, 1..=6.
     */
    size_t value_count;
    /**
     * The new declared values, bias first; entries past value_count are not
     * read.
     */
    double values[SIDEREON_CLOCK_MAX_VALUES];
} SidereonClockRecordValues;

/**
 * A data record read from the source that is not part of the satellite series.
 */
typedef struct SidereonClockSkip {
    /**
     * One-based line number where the record appears.
     */
    size_t line;
    /**
     * Record type, as SidereonClockRecordType.
     */
    uint32_t record_type;
} SidereonClockSkip;

/**
 * One GLONASS RINEX record skipped because its satellite token names no
 * satellite: a slot outside `01`..`99` such as `R00`, or a malformed slot
 * field.
 */
typedef struct SidereonSkippedGlonassRecord {
    /**
     * Raw satellite token from the skipped input record, such as `R00`.
     */
    struct SidereonSatelliteToken satellite;
} SidereonSkippedGlonassRecord;

typedef struct SidereonRinexLintFinding {
    char code[RINEX_QC_CODE_C_BYTES];
    uint32_t severity;
    bool repairable;
    bool has_epoch_index;
    size_t epoch_index;
    bool has_satellite;
    struct SidereonSatelliteToken satellite;
    bool has_field;
    char field[RINEX_QC_FIELD_C_BYTES];
} SidereonRinexLintFinding;

typedef struct SidereonRinexLintSummary {
    size_t finding_count;
    size_t fatal_count;
    size_t error_count;
    size_t warning_count;
    size_t info_count;
    bool is_clean;
    bool decoded_from_crinex;
} SidereonRinexLintSummary;

/**
 * One carrier-phase row with carrier metadata.
 */
typedef struct SidereonRinexObsCarrierPhase {
    /**
     * Satellite token.
     */
    struct SidereonSatelliteToken sat_id;
    /**
     * RINEX carrier observation code.
     */
    char code[RINEX_OBS_CODE_C_BYTES];
    /**
     * Whether value_cycles is present.
     */
    bool has_value_cycles;
    /**
     * Phase in cycles when present.
     */
    double value_cycles;
    /**
     * Loss-of-lock indicator, or -1 when absent.
     */
    int32_t lli;
    /**
     * Signal-strength indicator, or -1 when absent.
     */
    int32_t ssi;
    /**
     * Whether frequency_hz is present.
     */
    bool has_frequency_hz;
    /**
     * Carrier frequency, hertz.
     */
    double frequency_hz;
    /**
     * Whether wavelength_m is present.
     */
    bool has_wavelength_m;
    /**
     * Carrier wavelength, meters.
     */
    double wavelength_m;
    /**
     * Whether value_m is present.
     */
    bool has_value_m;
    /**
     * Carrier phase converted to meters.
     */
    double value_m;
    /**
     * Whether the header in effect at the epoch states one `SYS / PHASE SHIFT`
     * correction for this satellite's signal.
     */
    enum SidereonRinexCorrectionStatus phase_shift_status;
    /**
     * The phase-shift correction in cycles when phase_shift_status is
     * Available, and NaN otherwise. No record, or a blank correction, is an
     * available 0, as is every signal of a RINEX 4 file, whose records the
     * format says to ignore. RINEX 3 phases are already aligned, so this is
     * metadata and is not applied to value_cycles or value_m.
     */
    double phase_shift_cycles;
    /**
     * How many corrections the header block gives this signal when
     * phase_shift_status is Ambiguous, and 0 otherwise. Copy them with
     * sidereon_rinex_obs_carrier_phase_conflicts.
     */
    size_t phase_shift_conflict_count;
} SidereonRinexObsCarrierPhase;

/**
 * One correction an ambiguous header block gives a signal, in the order the
 * records give them.
 */
typedef struct SidereonRinexPhaseShiftCorrection {
    /**
     * Whether the record gives a correction. False for a record whose
     * correction field is blank.
     */
    bool has_cycles;
    /**
     * The correction in cycles when has_cycles is true, and NaN otherwise.
     */
    double cycles;
} SidereonRinexPhaseShiftCorrection;

/**
 * One per-system RINEX observation code from the header.
 */
typedef struct SidereonRinexObsCode {
    /**
     * GNSS system as SidereonGnssSystem.
     */
    uint32_t system;
    /**
     * Observation code, null-terminated.
     */
    char code[RINEX_OBS_CODE_C_BYTES];
} SidereonRinexObsCode;

/**
 * One parsed RINEX observation epoch summary.
 */
typedef struct SidereonRinexObsEpoch {
    /**
     * Whether epoch carries a time. False for an event record whose epoch
     * fields are blank, which RINEX 2.11 and 3.05 allow for an event without a
     * significant epoch; an observation or cycle-slip epoch always has one.
     */
    bool has_epoch;
    /**
     * Civil epoch in the file's time scale when has_epoch is true. When it is
     * false the integer fields are 0, which names no calendar date, and second
     * is NaN.
     */
    struct SidereonCalendarEpoch epoch;
    /**
     * RINEX epoch flag.
     */
    uint8_t flag;
    /**
     * Number of satellites observed at this epoch.
     */
    size_t satellite_count;
} SidereonRinexObsEpoch;

/**
 * Parsed RINEX observation header summary.
 */
typedef struct SidereonRinexObsHeader {
    /**
     * Full RINEX version.
     */
    double version;
    /**
     * Whether approx_position_m is present.
     */
    bool has_approx_position_m;
    /**
     * Surveyed a-priori receiver position, ECEF meters.
     */
    double approx_position_m[3];
    /**
     * Whether antenna_delta_hen_m is present.
     */
    bool has_antenna_delta_hen_m;
    /**
     * Antenna offset in RINEX height/east/north convention, meters.
     */
    double antenna_delta_hen_m[3];
    /**
     * Whether interval_s is present.
     */
    bool has_interval_s;
    /**
     * Nominal epoch spacing, seconds.
     */
    double interval_s;
    /**
     * Whether time_of_first_obs is present.
     */
    bool has_time_of_first_obs;
    /**
     * First observation epoch.
     */
    struct SidereonCalendarEpoch time_of_first_obs;
    /**
     * Time scale of time_of_first_obs as SidereonTimeScale.
     */
    uint32_t time_of_first_obs_scale;
    /**
     * Number of per-system observation-code rows.
     */
    size_t obs_code_count;
    /**
     * Number of phase-shift header rows.
     */
    size_t phase_shift_count;
    /**
     * Number of scale-factor header rows.
     */
    size_t scale_factor_count;
    /**
     * Number of GLONASS slot/channel rows.
     */
    size_t glonass_slot_count;
    /**
     * Whether marker_name is present.
     */
    bool has_marker_name;
    /**
     * Marker name, null-terminated when present.
     */
    char marker_name[RINEX_OBS_MARKER_C_BYTES];
} SidereonRinexObsHeader;

