/**
 * A line whose column 69 did not confirm its checksum.
 */
typedef struct SidereonTleChecksumWarning {
    /**
     * TLE line number, 1 or 2.
     */
    uint8_t line_number;
    /**
     * What column 69 held.
     */
    enum SidereonTleChecksumWarningKind kind;
    /**
     * The digit (MISMATCH) or byte (NOT_DIGIT) found in column 69; 0 for
     * MISSING.
     */
    uint8_t found;
    /**
     * Checksum recomputed from columns 1 through 68 (or as many as the line
     * has).
     */
    uint8_t computed;
} SidereonTleChecksumWarning;

/**
 * One rejected stretch of a TLE file.
 */
typedef struct SidereonTleRejectedRecord {
    /**
     * One-based line number of the first rejected line: the name line when
     * the record had one, otherwise its line 1 or line 2.
     */
    size_t line_number;
    /**
     * Why the lines were rejected.
     */
    enum SidereonTleRecordIssue issue;
} SidereonTleRejectedRecord;

/**
 * Parsed TLE element fields exposed as read-only metadata.
 */
typedef struct SidereonTleMetadata {
    /**
     * Null-terminated NORAD catalog number.
     */
    char catalog_number[32];
    /**
     * Null-terminated classification string.
     */
    char classification[32];
    /**
     * Null-terminated international designator.
     */
    char international_designator[32];
    /**
     * Four-digit epoch year.
     */
    int32_t epoch_year;
    /**
     * Fractional day-of-year of the epoch.
     */
    double epoch_day_of_year;
    /**
     * Inclination in degrees.
     */
    double inclination_deg;
    /**
     * Right ascension of the ascending node in degrees.
     */
    double raan_deg;
    /**
     * Orbital eccentricity.
     */
    double eccentricity;
    /**
     * Argument of perigee in degrees.
     */
    double arg_perigee_deg;
    /**
     * Mean anomaly at epoch in degrees.
     */
    double mean_anomaly_deg;
    /**
     * Mean motion in revolutions per day.
     */
    double mean_motion_rev_per_day;
    /**
     * First derivative of mean motion in revolutions per day squared.
     */
    double mean_motion_dot;
    /**
     * Second derivative of mean motion in revolutions per day cubed.
     */
    double mean_motion_double_dot;
    /**
     * B* drag term in TLE convention.
     */
    double bstar;
    /**
     * Whether line 1 states an ephemeris type (the field may be blank).
     */
    bool has_ephemeris_type;
    /**
     * Ephemeris type from line 1, zero when blank.
     */
    int32_t ephemeris_type;
    /**
     * Whether line 1 states an element set number.
     */
    bool has_elset_number;
    /**
     * Element set number from line 1, zero when blank.
     */
    int32_t elset_number;
    /**
     * Whether line 2 states a revolution number.
     */
    bool has_rev_number;
    /**
     * Revolution number at epoch, zero when blank.
     */
    int32_t rev_number;
} SidereonTleMetadata;

/**
 * Innovation report for a pending or applied track update.
 */
typedef struct SidereonTrackInnovation {
    /**
     * Measurement dimension.
     */
    size_t dimension;
    /**
     * Normalized innovation squared.
     */
    double nis;
} SidereonTrackInnovation;

/**
 * Prediction report from a no-IMU track filter.
 */
typedef struct SidereonTrackPrediction {
    /**
     * Propagation step, seconds.
     */
    double dt_s;
    /**
     * Predicted state metadata after the propagation.
     */
    struct SidereonTrackState predicted;
} SidereonTrackPrediction;

/**
 * Covariance-weighted track update report.
 */
typedef struct SidereonTrackUpdate {
    /**
     * State before applying the correction.
     */
    struct SidereonTrackState predicted;
    /**
     * State after applying the correction.
     */
    struct SidereonTrackState updated;
    /**
     * Innovation statistics for the correction.
     */
    struct SidereonTrackInnovation innovation;
} SidereonTrackUpdate;

/**
 * Gated track update report.
 */
typedef struct SidereonTrackGatedUpdate {
    /**
     * NIS gate result.
     */
    struct SidereonNisGate gate;
    /**
     * True when update contains an accepted correction.
     */
    bool has_update;
    /**
     * Accepted correction report when has_update is true; zeroed otherwise.
     */
    struct SidereonTrackUpdate update;
    /**
     * Current filter state metadata after the gated operation.
     */
    struct SidereonTrackState state;
} SidereonTrackGatedUpdate;

/**
 * One finished RTS history epoch.
 */
typedef struct SidereonTrackRtsEpoch {
    /**
     * Epoch seconds.
     */
    double t_s;
    /**
     * Prediction carried by the epoch.
     */
    struct SidereonTrackState predicted;
    /**
     * Update carried by the epoch.
     */
    struct SidereonTrackState updated;
    /**
     * Whether transition_from_previous is present for this epoch.
     */
    bool has_transition_from_previous;
} SidereonTrackRtsEpoch;

/**
 * Scalar summary of a converged trust-region solve.
 */
typedef struct SidereonTrlsSummary {
    /**
     * Final cost `0.5 * sum(residual^2)`.
     */
    double cost;
    /**
     * First-order optimality `||J^T f||_inf` at the solution.
     */
    double optimality;
    /**
     * Residual-evaluation count.
     */
    size_t nfev;
    /**
     * Jacobian-evaluation count.
     */
    size_t njev;
    /**
     * SciPy status: 0 max-eval, 1 gtol, 2 ftol, 3 xtol, 4 ftol+xtol.
     */
    int32_t status;
    /**
     * Whether the solve converged (status > 0).
     */
    bool success;
    /**
     * Parameter count `n` (length of the solution vector).
     */
    size_t n;
    /**
     * Residual count `m`.
     */
    size_t m;
} SidereonTrlsSummary;

/**
 * Troposphere mapping factors, mirroring
 * sidereon_core::atmosphere::troposphere::MappingFactors.
 */
typedef struct SidereonMappingFactors {
    /**
     * Hydrostatic (dry) mapping factor.
     */
    double dry;
    /**
     * Wet mapping factor.
     */
    double wet;
} SidereonMappingFactors;

/**
 * Typed troposphere mapping error detail.
 */
typedef struct SidereonTropoMappingError {
    /**
     * Error kind as SidereonTropoMappingErrorKind.
     */
    uint32_t kind;
    /**
     * Input elevation, radians.
     */
    double elevation_rad;
    /**
     * Minimum supported mapping elevation, radians.
     */
    double min_elevation_rad;
} SidereonTropoMappingError;

/**
 * Zenith troposphere delay split, mirroring
 * sidereon_core::atmosphere::troposphere::ZenithDelay.
 */
typedef struct SidereonZenithDelay {
    /**
     * Hydrostatic (dry) zenith delay, meters.
     */
    double dry_m;
    /**
     * Wet zenith delay, meters.
     */
    double wet_m;
} SidereonZenithDelay;

/**
 * UT1 and delta-T table metadata.
 */
typedef struct SidereonUt1CoverageInfo {
    /**
     * First Modified Julian Date in the UT1 table.
     */
    int32_t first_mjd;
    /**
     * Last Modified Julian Date in the UT1 table.
     */
    int32_t last_mjd;
    /**
     * First covered instant, TT Julian date.
     */
    double first_jd_tt;
    /**
     * Last covered instant, TT Julian date.
     */
    double last_jd_tt;
    /**
     * Number of table entries.
     */
    size_t entries;
    /**
     * Byte length of the provenance string, excluding a terminator.
     */
    size_t source_len;
} SidereonUt1CoverageInfo;

/**
 * One satellite visible above the elevation mask at a single instant.
 */
typedef struct SidereonVisibleSatellite {
    /**
     * Null-terminated caller-supplied satellite id (the matching `ids[i]` passed
     * to sidereon_visible_from_satellites). That input is bounded to at most
     * MAX_VISIBLE_ID_BYTES (64) bytes, so it always fits this buffer without
     * truncation. The buffer length is VISIBLE_ID_C_BYTES (MAX_VISIBLE_ID_BYTES
     * + 1).
     */
    char catalog_number[65];
    /**
     * Azimuth in degrees clockwise from north.
     */
    double azimuth_deg;
    /**
     * Elevation in degrees above the horizon.
     */
    double elevation_deg;
    /**
     * Slant range in kilometers.
     */
    double range_km;
    /**
     * TEME position in kilometers.
     */
    double position_km[3];
} SidereonVisibleSatellite;

/**
 * Baarda w-test constants for one false-alarm and missed-detection pair.
 */
typedef struct SidereonWTestNoncentrality {
    /**
     * Minimal normalized bias.
     */
    double delta0;
    /**
     * Noncentrality parameter, equal to delta0 squared.
     */
    double lambda0;
} SidereonWTestNoncentrality;

