enum SidereonStatus sidereon_constellation_validation_missing_sp3_ids(const struct SidereonConstellationValidation *validation,
                                                                      struct SidereonSatelliteToken *out,
                                                                      size_t len,
                                                                      size_t *out_written,
                                                                      size_t *out_required);

