enum SidereonStatus sidereon_glonass_g1_frequency_hz(int8_t channel, double *out);

/**
 * Write seconds of week for a calendar date and time, counted from Sunday
 * 00:00 in the date's own system time.
 *
 * The fields must name a calendar date and clock time: `month` in 1..=12,
 * `day` in 1 through the length of that month in the Gregorian calendar,
 * `hour` in 0..=23, `minute` in 0..=59 and `second` in 0..=60, where 60 is a
 * leap-second label. Any other field is refused with
 * SIDEREON_STATUS_INVALID_ARGUMENT and a thread-local message naming the
 * fields. `*out_sow_s` is set to NaN before the fields are read and keeps it on
 * a refusal, so a refused date never reads as a seconds-of-week value.
 *
 * Safety: out_sow_s points to a double.
 */
enum SidereonStatus sidereon_gnss_seconds_of_week_from_calendar(int64_t year,
                                                                int64_t month,
                                                                int64_t day,
                                                                int64_t hour,
                                                                int64_t minute,
                                                                int64_t second,
                                                                double *out_sow_s);

/**
 * Copy the core conventional GNSS system label into out.
 */
enum SidereonStatus sidereon_gnss_system_label(uint32_t system,
                                               uint8_t *out,
                                               size_t len,
                                               size_t *out_written,
                                               size_t *out_required);

/**
 * Split continuous seconds since a system week epoch into week and seconds of
 * week.
 *
 * Safety: out_week and out_sow_s point to doubles.
 */
enum SidereonStatus sidereon_gnss_week_and_seconds_of_week(double continuous_seconds,
                                                           double *out_week,
                                                           double *out_sow_s);

/**
 * Write the Julian Day Number of a system's week epoch, when present.
 *
 * Safety: out_present points to a bool; out_jdn points to an int64_t.
 */
enum SidereonStatus sidereon_gnss_week_epoch_julian_day_number(uint32_t system,
                                                               bool *out_present,
                                                               int64_t *out_jdn);

/**
 * Write the GNSS week for a calendar date, when present.
 *
 * `*out_present` is false, with `*out_week` 0, for a date before the system's
 * week epoch, for a scale without GNSS weeks, and for fields that name no
 * calendar date: a month outside 1..=12 or a day outside that month. The
 * engine reports all three as one absence, so this call does not tell them
 * apart.
 *
 * Safety: out_present points to a bool; out_week points to a uint32_t; their
 * output ranges must be disjoint.
 */
enum SidereonStatus sidereon_gnss_week_from_calendar(uint32_t system,
                                                     int64_t year,
                                                     int64_t month,
                                                     int64_t day,
                                                     bool *out_present,
                                                     uint32_t *out_week);

/**
 * Construct a GNSS week/TOW value.
 *
 * Safety: out must point to a SidereonGnssWeekTow.
 */
enum SidereonStatus sidereon_gnss_week_tow_new(uint32_t system,
                                               uint32_t week,
                                               double tow_s,
                                               struct SidereonGnssWeekTow *out);

/**
 * Normalize a GNSS week/TOW value.
 *
 * Safety: value and out must point to SidereonGnssWeekTow values.
 */
enum SidereonStatus sidereon_gnss_week_tow_normalized(const struct SidereonGnssWeekTow *value,
                                                      struct SidereonGnssWeekTow *out);

/**
 * Apply 1024-week rollovers to a GNSS week/TOW value.
 *
 * Safety: value points to a SidereonGnssWeekTow; out_week points to a uint32_t.
 */
enum SidereonStatus sidereon_gnss_week_tow_unrolled_week(const struct SidereonGnssWeekTow *value,
                                                         uint32_t rollovers,
                                                         uint32_t *out_week);

/**
 * GPS - UTC (the GNSS leap-second offset a GPS receiver applies, IS-GPS-200) at
 * a UTC Julian date, written to *out. 18 s from 2017-01-01. Delegates to the
 * core `gps_utc_offset_s`. This is NOT TAI - UTC (use
 * sidereon_tai_utc_offset_s); the two differ by a constant 19 s.
 *
 * Safety: out must point to a double.
 */
enum SidereonStatus sidereon_gps_utc_offset_s(double jd_utc, double *out);

/**
 * Write the number of points in a ground-track arc to *out_count.
 *
 * Safety: track must be a live handle; out_count must point to a size_t.
 */
enum SidereonStatus sidereon_ground_track_count(const struct SidereonGroundTrack *track,
                                                size_t *out_count);

/**
 * Release a ground-track handle. Null is a no-op. A non-null handle must come
 * from sidereon_tle_ground_track and must be freed exactly once with this
 * function.
 *
 * Safety: track must be NULL or a live handle from sidereon_tle_ground_track.
 * Passing a handle after it has already been freed is invalid.
 */
void sidereon_ground_track_free(struct SidereonGroundTrack *track);

/**
 * Copy ground-track sub-satellite geodetic points. Uses the variable-length
 * output contract documented at the top of the header.
 *
 * Safety: track must be a live handle; out must point to at least len writable
 * entries or be NULL when len is 0; out_written and out_required must point to
 * size_t values.
 */
enum SidereonStatus sidereon_ground_track_values(const struct SidereonGroundTrack *track,
                                                 struct SidereonGeodetic *out,
                                                 size_t len,
                                                 size_t *out_written,
                                                 size_t *out_required);

/**
 * Trace of the Gauss-Newton Hessian approximation `J^T J` (the sum of squared
 * column norms) of a row-major `m`-by-`n` Jacobian, written to *out. Delegates
 * to the core `hessian_trace`; forms no inverse.
 *
 * Safety: jacobian must point to m*n readable doubles (or be NULL when m*n is
 * 0); out must point to a double.
 */
enum SidereonStatus sidereon_hessian_trace(const double *jacobian, size_t m, size_t n, double *out);

