/**
 * Write the number of skipped (unresolved) OMM entries to *out_count.
 *
 * Safety: catalog must be a live handle; out_count must point to a size_t.
 */
enum SidereonStatus sidereon_omm_catalog_skipped_count(const struct SidereonOmmCatalog *catalog,
                                                       size_t *out_count);

/**
 * Copy the OBJECT_NAME of one skipped OMM entry (by zero-based index) into out
 * using the variable-length output contract documented at the top of the header.
 * The output is the UTF-8 name bytes and is not null-terminated. When the entry
 * carried no object name (object_name_present is false in
 * sidereon_omm_catalog_skipped), *out_required is 0 and nothing is written. Fails
 * with SIDEREON_STATUS_INVALID_ARGUMENT if index is out of range.
 *
 * Safety: catalog must be a live handle; out must point to at least len writable
 * bytes or be NULL when len is 0; out_written and out_required must point to
 * size_t values.
 */
enum SidereonStatus sidereon_omm_catalog_skipped_object_name(const struct SidereonOmmCatalog *catalog,
                                                             size_t index,
                                                             uint8_t *out,
                                                             size_t len,
                                                             size_t *out_written,
                                                             size_t *out_required);

/**
 * Release an OMM handle. Passing NULL is a no-op.
 *
 * Safety: omm must be a handle from a sidereon_omm_parse_* call or NULL.
 */
void sidereon_omm_free(struct SidereonOmm *omm);

/**
 * Parse an OMM from JSON text (a single OMM object). On success writes a newly
 * owned handle to *out_omm. Delegates to sidereon_core::astro::omm::parse_json.
 *
 * Safety: data points to len readable bytes; out_omm points to a SidereonOmm*.
 */
enum SidereonStatus sidereon_omm_parse_json(const uint8_t *data,
                                            size_t len,
                                            struct SidereonOmm **out_omm);

/**
 * Parse an OMM from KVN text. On success writes a newly owned handle to
 * *out_omm. Delegates to sidereon_core::astro::omm::parse_kvn.
 *
 * Safety: data points to len readable bytes; out_omm points to a SidereonOmm*.
 */
enum SidereonStatus sidereon_omm_parse_kvn(const uint8_t *data,
                                           size_t len,
                                           struct SidereonOmm **out_omm);

/**
 * Parse an OMM from XML text. On success writes a newly owned handle to
 * *out_omm. Delegates to sidereon_core::astro::omm::parse_xml.
 *
 * Safety: data points to len readable bytes; out_omm points to a SidereonOmm*.
 */
enum SidereonStatus sidereon_omm_parse_xml(const uint8_t *data,
                                           size_t len,
                                           struct SidereonOmm **out_omm);

/**
 * Serialize an OMM to JSON text (not null-terminated). Round-trips with
 * sidereon_omm_parse_json. Variable-length output contract. Delegates to
 * sidereon_core::astro::omm::encode_json.
 * Fails with SIDEREON_STATUS_INVALID_ARGUMENT when the writer refuses the
 * message, naming the item it cannot write.
 *
 * Safety: omm is a live handle; out points to len writable bytes or NULL when
 * len is 0; out_written and out_required point to size_t.
 */
enum SidereonStatus sidereon_omm_to_json(const struct SidereonOmm *omm,
                                         uint8_t *out,
                                         size_t len,
                                         size_t *out_written,
                                         size_t *out_required);

/**
 * Serialize an OMM to KVN text (not null-terminated). Round-trips with
 * sidereon_omm_parse_kvn. Variable-length output contract. Delegates to
 * sidereon_core::astro::omm::encode_kvn.
 * Fails with SIDEREON_STATUS_INVALID_ARGUMENT when the writer refuses the
 * message, naming the item it cannot write.
 *
 * Safety: omm is a live handle; out points to len writable bytes or NULL when
 * len is 0; out_written and out_required point to size_t.
 */
enum SidereonStatus sidereon_omm_to_kvn(const struct SidereonOmm *omm,
                                        uint8_t *out,
                                        size_t len,
                                        size_t *out_written,
                                        size_t *out_required);

/**
 * Serialize an OMM to XML text (not null-terminated). Round-trips with
 * sidereon_omm_parse_xml. Variable-length output contract. Delegates to
 * sidereon_core::astro::omm::encode_xml.
 * Fails with SIDEREON_STATUS_INVALID_ARGUMENT when the writer refuses the
 * message, naming the item it cannot write.
 *
 * Safety: omm is a live handle; out points to len writable bytes or NULL when
 * len is 0; out_written and out_required point to size_t.
 */
enum SidereonStatus sidereon_omm_to_xml(const struct SidereonOmm *omm,
                                        uint8_t *out,
                                        size_t len,
                                        size_t *out_written,
                                        size_t *out_required);

/**
 * Release an OPM handle from a sidereon_opm_parse_* call. Passing NULL is a
 * no-op.
 *
 * Safety: opm must be NULL or a live handle that has not already been freed.
 */
void sidereon_opm_free(struct SidereonOpm *opm);

/**
 * Parse a CCSDS OPM in KVN (keyword=value) form. On success writes a newly
 * owned handle to *out_opm. Release it with sidereon_opm_free.
 *
 * Safety: data must point to len readable bytes; out_opm must point to storage
 * for a SidereonOpm*.
 */
enum SidereonStatus sidereon_opm_parse_kvn(const uint8_t *data,
                                           size_t len,
                                           struct SidereonOpm **out_opm);

/**
 * Parse a CCSDS OPM in XML (NDM/XML) form. On success writes a newly owned
 * handle to *out_opm. Release it with sidereon_opm_free.
 *
 * Safety: data must point to len readable bytes; out_opm must point to storage
 * for a SidereonOpm*.
 */
enum SidereonStatus sidereon_opm_parse_xml(const uint8_t *data,
                                           size_t len,
                                           struct SidereonOpm **out_opm);

/**
 * Serialize an OPM to KVN text. The output is not null-terminated. Uses the
 * variable-length output contract documented at the top of the header: call once
 * with out=NULL to learn *out_required, then again with a buffer of that size.
 * Round-trips with sidereon_opm_parse_kvn.
 * Fails with SIDEREON_STATUS_INVALID_ARGUMENT when the writer refuses the
 * message, naming the item it cannot write.
 *
 * Safety: opm must be a live handle; out must point to at least len writable
 * bytes or be NULL when len is 0; out_written and out_required must point to
 * size_t.
 */
enum SidereonStatus sidereon_opm_to_kvn(const struct SidereonOpm *opm,
                                        uint8_t *out,
                                        size_t len,
                                        size_t *out_written,
                                        size_t *out_required);

/**
 * Serialize an OPM to XML text. The output is not null-terminated. Uses the
 * variable-length output contract documented at the top of the header: call once
 * with out=NULL to learn *out_required, then again with a buffer of that size.
 * Round-trips with sidereon_opm_parse_xml.
 * Fails with SIDEREON_STATUS_INVALID_ARGUMENT when the writer refuses the
 * message, naming the item it cannot write.
 *
 * Safety: opm must be a live handle; out must point to at least len writable
 * bytes or be NULL when len is 0; out_written and out_required must point to
 * size_t.
 */
enum SidereonStatus sidereon_opm_to_xml(const struct SidereonOpm *opm,
                                        uint8_t *out,
                                        size_t len,
                                        size_t *out_written,
                                        size_t *out_required);

