/**
 * Release an SPK kernel handle returned by sidereon_spk_load. Passing NULL is
 * a no-op.
 *
 * Safety: spk must be NULL or a live handle from sidereon_spk_load that has not
 * already been freed.
 */
void sidereon_spk_free(struct SidereonSpk *spk);

/**
 * Parse a JPL/NAIF SPK (DAF/SPK `.bsp`) ephemeris kernel from a byte buffer.
 * On success writes a newly owned handle to *out_spk. Release it with
 * sidereon_spk_free.
 *
 * Safety: data must point to len readable bytes; out_spk must point to storage
 * for a SidereonSpk*.
 */
enum SidereonStatus sidereon_spk_load(const uint8_t *data,
                                      size_t len,
                                      struct SidereonSpk **out_spk);

/**
 * Query the state of NAIF `target` relative to NAIF `center` at
 * `et_seconds_tdb` (ET/TDB seconds past J2000), writing the resolved relative
 * state into *out_state. Chooses segments as CSPICE `SPKSFS` and `SPKGEO` do
 * (for each body the highest-priority segment covering the epoch, the later
 * segment first) and evaluates SPK Types 2, 3, and 21. The numbers are exactly what the
 * engine's SPK reader produces.
 *
 * Safety: spk must be a live handle from sidereon_spk_load that has not been
 * freed; out_state must point to a SidereonSpkState.
 */
enum SidereonStatus sidereon_spk_state(const struct SidereonSpk *spk,
                                       int32_t target,
                                       int32_t center,
                                       double et_seconds_tdb,
                                       struct SidereonSpkState *out_state);

/**
 * Query the state of NAIF `target` relative to NAIF `center` at
 * `et_seconds_tdb` in the NAIF frame `frame`, as CSPICE `SPKGEO` does with
 * the reference frame `REF`: segments are chosen as for sidereon_spk_state
 * and the composed state is rotated into `frame` with the constant NAIF
 * inertial-frame rotation when it is expressed in another frame. A rotation
 * involving a frame outside the NAIF inertial frames 1-21 fails with
 * SIDEREON_STATUS_SOLVE.
 *
 * Safety: spk must be a live handle from sidereon_spk_load that has not been
 * freed; out_state must point to a SidereonSpkState.
 */
enum SidereonStatus sidereon_spk_state_in_frame(const struct SidereonSpk *spk,
                                                int32_t target,
                                                int32_t center,
                                                double et_seconds_tdb,
                                                int32_t frame,
                                                struct SidereonSpkState *out_state);

/**
 * J2000 seconds for a split Julian date. Delegates to
 * sidereon_core::astro::time::civil::j2000_seconds_from_split (infallible).
 *
 * Safety: out must point to a double.
 */
enum SidereonStatus sidereon_split_jd_to_j2000_seconds(double jd_whole,
                                                       double jd_fraction,
                                                       double *out);

/**
 * Write the number of per-epoch results in a batch to *out_count.
 *
 * Safety: batch is a live handle; out_count points to a size_t.
 */
enum SidereonStatus sidereon_spp_batch_count(const struct SidereonSppBatch *batch,
                                             size_t *out_count);

/**
 * Write whether epoch `index` solved to *out_ok.
 *
 * Safety: batch is a live handle; out_ok points to a bool.
 */
enum SidereonStatus sidereon_spp_batch_epoch_ok(const struct SidereonSppBatch *batch,
                                                size_t index,
                                                bool *out_ok);

/**
 * Copy epoch `index`'s solve-failure message into a caller buffer (not
 * null-terminated). An epoch that solved reports *out_required 0 and writes
 * nothing. Variable-length output contract.
 *
 * Safety: batch is a live handle; out points to len writable bytes or NULL when
 * len is 0; out_written and out_required point to size_t.
 */
enum SidereonStatus sidereon_spp_batch_error(const struct SidereonSppBatch *batch,
                                             size_t index,
                                             uint8_t *out,
                                             size_t len,
                                             size_t *out_written,
                                             size_t *out_required);

/**
 * Read the structured error summary for epoch `index` in an SPP batch.
 * An epoch that solved reports SidereonEngineErrorFamily::None and payload_len 0.
 *
 * Safety: batch is a live handle; out_info points to a SidereonEngineErrorInfo.
 */
enum SidereonStatus sidereon_spp_batch_error_info(const struct SidereonSppBatch *batch,
                                                  size_t index,
                                                  struct SidereonEngineErrorInfo *out_info);

/**
 * Copy the owned Schema 1 UTF-8 JSON payload for epoch `index` in an SPP batch.
 * Follows standard variable-length copy semantics. An epoch that solved reports
 * *out_written 0 and *out_required 0.
 *
 * Safety: batch is a live handle; out points to len writable bytes or NULL when
 * len is 0; out_written and out_required point to size_t.
 */
enum SidereonStatus sidereon_spp_batch_error_payload(const struct SidereonSppBatch *batch,
                                                     size_t index,
                                                     uint8_t *out,
                                                     size_t len,
                                                     size_t *out_written,
                                                     size_t *out_required);

/**
 * Release a batch SPP handle. Passing NULL is a no-op.
 *
 * Safety: batch must be a handle from a sidereon_solve_spp_batch_* call or NULL.
 */
void sidereon_spp_batch_free(struct SidereonSppBatch *batch);

/**
 * Copy epoch `index`'s solution into a newly owned SidereonSppSolution handle,
 * readable with the ordinary sidereon_spp_solution_* accessors and released with
 * sidereon_spp_solution_free. Returns SIDEREON_STATUS_SOLVE if that epoch did
 * not solve (its message is recorded for sidereon_last_error_message).
 *
 * Safety: batch is a live handle; out_solution points to storage for a
 * SidereonSppSolution*.
 */
enum SidereonStatus sidereon_spp_batch_solution(const struct SidereonSppBatch *batch,
                                                size_t index,
                                                struct SidereonSppSolution **out_solution);

